import{_ as e,c as a,o as t,f as n}from"./chunks/framework.BOAZPCR7.js";const f=JSON.parse('{"title":"The SARS-CoV-2 spike receptor-binding domain has evolved decreased inherent antigenicity in humans","description":"","frontmatter":{"layout":"post","title":"The SARS-CoV-2 spike receptor-binding domain has evolved decreased inherent antigenicity in humans","date":"2026-10-21T00:00:00.000Z","author":"Jesse Bloom","head":[["link",{"rel":"canonical","href":"https://jbloomlab.org/posts/2026-10-21_jacobdolan.html"}]]},"headers":[],"relativePath":"posts/2026-10-21_jacobdolan.md","filePath":"posts/2026-10-21_jacobdolan.md"}'),r={name:"posts/2026-10-21_jacobdolan.md"},i=n('<p>In a <a href="https://doi.org/10.64898/2026.10.15.759476" target="_blank" rel="noreferrer">new study</a> led by Catherine Jacob-Dolan, we show SARS-CoV-2&#39;s spike RBD has evolved reduced inherent antigenicity as quantified by decreased recognition by naive human B cells.</p><hr><p>It&#39;s been clear for some time now that SARS-CoV-2 evolves to escape the antibodies elicited by prior infection and vaccination. In this study, we asked a different question: Has it also evolved to reduce its recognition by naive human B cells?</p><p>To answer this question, we measured the percentage of naive human B cells (from pre-2019 human samples) that bound to the spike RBD from the early Wuhan-Hu-1 variant or several later variants. We found a roughly 3-fold decrease in binding of naive human B cells to later variants. In contrast, there was no decrease in binding to naive mice B cells, indicating a specific loss of recognition by the human naive antibody repertoire.</p><p>Our interpretation: early viral variant RBDs are strongly targeted by “public” human germline antibodies, putting pressure on virus to change those epitopes. As the epitopes evolve, sometimes they become less recognized by human germline repertoire, decreasing inherent antigenicity.</p><p>However, the decrease in inherent antigenicity is modest (~3-fold), and plenty of naïve human B cells still bind newer variant RBDs. We lack data to assess how much ~3-fold drop in inherent antigenicity affects human neutralizing antibody response. This is an interesting area for future work.</p><p>For more details, see:</p><ul><li><a href="https://doi.org/10.64898/2026.10.15.759476" target="_blank" rel="noreferrer">The full preprint</a></li><li><a href="https://bsky.app/profile/jbloomlab.bsky.social/post/3myfaa7mgl22c" target="_blank" rel="noreferrer">Bluesky thread</a>, more easily read <a href="https://skywriter.blue/@jbloomlab.bsky.social/3myfaa7mgl22c" target="_blank" rel="noreferrer">in threaded form here</a></li><li><a href="https://x.com/jbloom_lab/status/2112894974924922968" target="_blank" rel="noreferrer">X thread</a></li></ul>',8),o=[i];function s(l,c,d,h,p,m){return t(),a("div",null,o)}const b=e(r,[["render",s]]);export{f as __pageData,b as default};
